// Contoh mengubah satu cerita: LONG[0]={title:'...',owner:'...',place:'...',img:'',paras:['...','...']};
// =====================================================================
SINS.forEach((s,i)=>{if(!s.img&&PICS[i])s.img=PICS[i]});
const R=['I','II','III','IV','V','VI','VII'],$=s=>document.querySelector(s);
const el=(t,c,x)=>{const e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e};
SINS.forEach((s,i)=>{const d=el('div','sin rv');d.append(el('b',0,R[i]),el('h3',0,s.n+' · '+s.l),el('p',0,s.d));$('#sinlist').append(d);
const c=el('div','card'),inn=el('div','in'),fr=el('div','face'),bk=el('div','face back');
if(s.img){const im=new Image();im.src=s.img;im.alt='Kartu pos '+s.n;fr.append(im)}else fr.append(el('div','ph','KARTU POS '+R[i]+'\n(tambahkan gambar)'));
const mo=el('a','more','Baca Cerita Lengkap →');mo.href='#cerita-'+(i+1);mo.onclick=e=>e.stopPropagation();
bk.append(el('h4',0,'KISAH · '+s.n.toUpperCase()),el('div',0,s.story),mo);inn.append(fr,bk);c.append(inn);
const cap=el('div','cap');cap.append(el('span',0,R[i]),el('h3',0,s.n));
const w=el('div','fl');w.style.cssText='--fx:'+((Math.random()*120-60)|0)+'vw;--fy:'+(-((Math.random()*40+60)|0))+'vh;--fr:'+((Math.random()*90-45)|0)+'deg;--fd:'+(i*.12)+'s';w.append(c,cap);c.onclick=()=>c.classList.toggle('f');$('#cards').append(w);
});

// routing
const pages=['beranda','kartu','kuis','tentang'];
function showStory(i){const L=LONG[i],S=SINS[i],b=$('#story');b.textContent='';
const bl=el('a','back-l','← Kembali ke Kartu Pos');bl.href='#kartu';
const pic=el('div','pic');const src=L.img||S.img;if(src){const im=new Image();im.src=src;im.alt='Kartu pos '+S.n;pic.append(im)}else pic.append(el('div','ph','GAMBAR KARTU POS '+R[i]));
b.append(bl,el('div','sub rv','Dosa '+R[i]+' · '+S.l),el('h2','rv',L.title),el('div','meta','OLEH '+L.owner.toUpperCase()+' · '+L.place.toUpperCase()),pic);
L.paras.forEach(t=>{let e;if(t.startsWith('## ')){e=el('h3','rv',t.slice(3));e.style.cssText='text-align:center;margin:44px 0 22px;color:var(--red);font-size:18px'}else if(t.startsWith('> ')){e=el('blockquote','rv',t.slice(2));e.style.cssText='white-space:pre-line;border-left:2px solid var(--red);background:#0d0708;padding:18px 22px;margin:28px 0;font-style:italic'}else e=el('p','rv',t);b.append(e)});
const n=el('div','snav'),pv=el('a',0,i>0?'← '+SINS[i-1].n:'');if(i>0)pv.href='#cerita-'+i;
const nx=el('a',0,i<6?SINS[i+1].n+' →':'');if(i<6)nx.href='#cerita-'+(i+2);n.append(pv,nx);b.append(n);b.querySelector('.sub').style.textAlign='center'}
function route(){let h=location.hash.slice(1),m=h.match(/^cerita-([1-7])$/),pid=h;
if(m){showStory(+m[1]-1);pid='cerita';h='kartu'}else if(!pages.includes(h))pid=h='beranda';
document.querySelectorAll('.pg').forEach(p=>p.classList.toggle('on',p.id===pid));
document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+h));
const kp=$('#kartu');kp.classList.remove('go');if(pid==='kartu')setTimeout(()=>kp.classList.add('go'),80);
const kq=$('#kuis'),sw=$('.sclw');kq.classList.remove('go2');sw.classList.remove('done');clearTimeout(window._qt);
if(pid==='kuis'){const fin=()=>{window._qd=1;sw.classList.add('done');kq.classList.add('go2')},rm=matchMedia('(prefers-reduced-motion:reduce)').matches;if(rm)sw.querySelector('svg').pauseAnimations();if(window._qd||rm)setTimeout(fin,40);else window._qt=setTimeout(fin,1500)}
scrollTo(0,0);setTimeout(()=>document.querySelectorAll('#'+pid+' .rv').forEach(e=>io.observe(e)),50)}
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('v');io.unobserve(e.target)}}),{threshold:.12});
addEventListener('hashchange',route);

// embers
(function(){const c=$('#embers'),x=c.getContext('2d');let W,H,P=[];
function rs(){W=c.width=c.offsetWidth;H=c.height=c.offsetHeight}rs();addEventListener('resize',rs);
const mk=()=>({x:Math.random()*W,y:H+10,r:Math.random()*2+.5,v:Math.random()*.6+.2,s:Math.random()*Math.PI*2,a:Math.random()*.6+.2});
for(let i=0;i<60;i++){const p=mk();p.y=Math.random()*H;P.push(p)}
(function f(){x.clearRect(0,0,W,H);P.forEach((p,i)=>{p.y-=p.v;p.s+=.02;p.x+=Math.sin(p.s)*.4;
x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.fillStyle='rgba(190,25,40,'+p.a*(p.y/H)+')';x.shadowColor='#c0182a';x.shadowBlur=8;x.fill();
if(p.y<-10)P[i]=mk()});requestAnimationFrame(f)})()})();

// quiz
// ====== KUIS 30 PERNYATAAN (skala 1-5) ======
// Urutan kelompok = urutan SINS: Pride, Greed, Wrath, Envy, Lust, Gluttony, Sloth
const LK=['Sangat tidak setuju','Tidak setuju','Netral / kadang-kadang','Setuju','Sangat setuju'];
const ENG=['Pride','Greed','Wrath','Envy','Lust','Gluttony','Sloth'];
const BANK=[
/*Pride (5)*/["Aku merasa sulit menerima ketika orang lain mengkritik hasil pekerjaanku.","Aku ingin orang lain mengakui kemampuan dan pencapaianku.","Aku merasa tidak nyaman ketika seseorang lebih unggul dariku.","Aku sering berusaha mempertahankan pendapat meskipun menyadari bahwa aku mungkin salah.","Aku terkadang menganggap pendapatku lebih benar daripada pendapat orang lain."],
/*Greed (4)*/["Aku selalu ingin memiliki lebih banyak, meskipun sebenarnya sudah cukup.","Aku merasa sulit mengeluarkan uang untuk orang lain meskipun aku mampu.","Aku merasa takut kehilangan sesuatu yang sudah menjadi milikku.","Aku terkadang mengutamakan keuntungan pribadi daripada kepentingan bersama."],
/*Wrath (4)*/["Aku mudah kehilangan kesabaran ketika sesuatu tidak berjalan sesuai keinginanku.","Aku sulit memaafkan seseorang meskipun orang tersebut sudah meminta maaf.","Ketika marah, aku terkadang mengatakan sesuatu yang kemudian kusesali.","Aku merasa ingin membalas perlakuan buruk yang pernah kuterima."],
/*Envy (4)*/["Aku merasa tidak nyaman ketika melihat orang lain mendapatkan sesuatu yang sangat kuinginkan.","Aku merasa pencapaian orang lain membuat pencapaianku terlihat kurang berarti.","Aku terkadang berharap seseorang gagal ketika mereka memiliki sesuatu yang tidak kumiliki.","Aku sulit merasa benar-benar bahagia atas keberhasilan orang yang membuatku iri."],
/*Lust (4)*/["Aku sering membiarkan keinginan sesaat memengaruhi keputusan yang kuambil.","Aku mudah terobsesi pada seseorang yang menarik perhatianku.","Aku senang mendapatkan perhatian dan validasi dari orang yang kusukai.","Aku pernah mengorbankan prinsip pribadi demi mendapatkan perhatian atau kasih sayang."],
/*Gluttony (4)*/["Aku sering mengonsumsi sesuatu secara berlebihan meskipun tidak benar-benar membutuhkannya.","Aku sulit berhenti ketika sedang menikmati sesuatu yang kusukai.","Aku menggunakan hiburan, makanan, atau belanja untuk mengisi kekosongan emosional.","Aku sering menyesal setelah menghabiskan terlalu banyak waktu atau uang untuk kesenangan sesaat."],
/*Sloth (5)*/["Aku sering menunda sesuatu meskipun tahu bahwa hal tersebut penting.","Aku memiliki banyak rencana, tetapi sulit mengambil langkah pertama.","Aku mudah kehilangan motivasi ketika menghadapi kesulitan.","Aku membiarkan kesempatan berlalu karena terlalu lama mempertimbangkan tindakan.","Aku terkadang mengetahui apa yang harus kulakukan, tetapi tetap memilih untuk tidak melakukannya."]];
const QS=BANK.flatMap((a,s)=>a.map(t=>[s,t]));
const DESC=['Kamu mungkin memiliki keinginan kuat untuk diakui, dihargai, dan dianggap mampu. Namun, terkadang kebutuhan untuk mempertahankan citra diri membuatmu sulit menerima kelemahan dan membuka diri terhadap orang lain.',
'Kamu mungkin sering merasa ada yang kurang, seolah garis cukup terus bergeser menjauh. Dorongan untuk memiliki dan mengamankan membuatmu sulit menikmati apa yang sudah ada, dan sulit melepaskannya untuk orang lain.',
'Kamu mungkin merasakan segala sesuatu dengan sangat dalam, terutama ketidakadilan dan rasa tidak dihargai. Amarah bisa menjadi pelindung, tetapi bila dipelihara, ia menahan luka lama dan menjauhkanmu dari orang yang kau sayangi.',
'Kamu mungkin memiliki mata yang tajam terhadap apa yang sebenarnya didambakan hatimu. Membandingkan diri bisa menunjukkan impianmu, tetapi juga mencuri rasa syukur atas perjalananmu sendiri.',
'Kamu mungkin hidup dengan keinginan yang kuat dan mudah tergerak oleh apa yang memikat. Di balik pencarian itu, sering ada kebutuhan untuk dilihat, dicintai, dan merasa hidup.',
'Kamu mungkin mencari kenyamanan lewat kesenangan, entah makanan, hiburan, atau belanja. Menikmati itu wajar, tetapi saat kesenangan dipakai untuk mengisi kekosongan, rasa puasnya cepat menghilang.',
'Kamu mungkin tahu persis apa yang perlu dilakukan, tetapi tenaga untuk memulainya terasa jauh. Menunda sering bukan soal malas, melainkan lelah, takut gagal, atau bingung harus mulai dari mana.'];
let order=[],qi=0,ans=[];
function startQ(){order=QS.map((_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}qi=0;ans=[];rq()}
function rq(){const b=$('#quiz');b.textContent='';
if(qi>=order.length){const sc=[0,0,0,0,0,0,0],mx=[0,0,0,0,0,0,0];
order.forEach((q,k)=>{const s=QS[q][0];sc[s]+=ans[k];mx[s]+=5});
const pc=sc.map((v,i)=>Math.round(v/mx[i]*1000)),top=Math.max(...pc),win=[0,1,2,3,4,5,6].filter(i=>pc[i]===top),r=el('div','res');
r.append(el('div','cz','THE RESULT OF YOUR REFLECTION'),el('div','orn','\u2726'),el('div','cz','YOUR DOMINANT SIN'+(win.length>1?'S':'')));
win.forEach(w=>r.append(el('div','big',SINS[w].n),el('div','cz',ENG[w].toUpperCase()+' \u00b7 '+SINS[w].l.toUpperCase()),el('div','cz','YOUR REFLECTION'),el('p',0,DESC[w])));
const bd=el('div');bd.style.cssText='text-align:left;margin:26px 0 6px';
[0,1,2,3,4,5,6].sort((a,c)=>pc[c]-pc[a]).forEach(s=>{const row=el('div','sb'),tr=el('div','tr'),f=el('i');f.style.width=(sc[s]/mx[s]*100)+'%';tr.append(f);row.append(el('span',0,SINS[s].n),tr,el('span',0,sc[s]+'/'+mx[s]));bd.append(row)});
const a=el('button','btn','Ulangi Refleksi');a.onclick=startQ;
const l=el('a','btn','Lihat Kartu Pos');l.href='#kartu';r.append(bd,a,l,el('div','note','Hasil ini hanya refleksi diri, bukan penilaian benar atau salah.'));b.append(r);return}
const bar=el('div','bar'),i=el('i');i.style.width=(qi/order.length*100)+'%';bar.append(i);
b.append(bar,el('div','cz','PERNYATAAN '+(qi+1)+' / '+order.length),el('div','q',QS[order[qi]][1]));
LK.forEach((t,k)=>{const x=el('button','opt',(k+1)+' \u00b7 '+t);x.onclick=()=>{ans[qi]=k+1;qi++;rq()};b.append(x)});
if(qi>0){const bk=el('button','more','\u2190 Sebelumnya');bk.style.cssText='background:none;cursor:pointer;font-family:Cinzel,serif';bk.onclick=()=>{qi--;rq()};b.append(bk)}}
startQ();

