// intro kelelawar
(function(){const I=$('#intro'),h=location.hash.slice(1);
if((h&&h!=='beranda')||matchMedia('(prefers-reduced-motion:reduce)').matches){I.remove();return}
document.body.style.overflow='hidden';
const c=$('#bats'),x=c.getContext('2d');let W,H,done=false,B=[],t0=performance.now();
function rs(){W=c.width=innerWidth;H=c.height=innerHeight}rs();addEventListener('resize',rs);
const N=innerWidth<700?16:30;
function mk(){const d=Math.random()<.5?1:-1,s=Math.random()*.9+.35;return{x:d>0?-90:W+90,y:Math.random()*H*.85+H*.05,s,d,v:(Math.random()*2.4+1.8)*(s+.5),w:Math.random()*6.28,fs:Math.random()*.15+.3,a:Math.random()*6.28,amp:Math.random()*1.1+.3}}
function wing(k,f){x.save();x.scale(k,1);x.beginPath();x.moveTo(3,-2);x.bezierCurveTo(14,-14-14*f,30,-20-20*f,48,-8-30*f);x.quadraticCurveTo(40,-4-8*f,36,4-4*f);x.quadraticCurveTo(30,-2,24,8);x.quadraticCurveTo(18,0,12,10);x.quadraticCurveTo(7,6,3,12);x.closePath();x.fill();x.stroke();x.restore()}
function bat(b){const f=Math.sin(b.w);x.save();x.translate(b.x,b.y);x.scale(b.s*b.d,b.s);x.rotate(Math.sin(b.a)*.12);
x.fillStyle='#0a0203';x.strokeStyle='#7a0f1a';x.lineWidth=1;x.shadowColor='#8b0f1a';x.shadowBlur=10;
wing(1,f);wing(-1,f);x.beginPath();x.ellipse(0,3,4.5,9,0,0,7);x.fill();x.beginPath();x.arc(0,-7,3.6,0,7);x.fill();
x.beginPath();x.moveTo(-3.4,-8);x.lineTo(-4.2,-14);x.lineTo(-0.8,-10);x.moveTo(3.4,-8);x.lineTo(4.2,-14);x.lineTo(0.8,-10);x.fill();
x.fillStyle='#c0182a';x.shadowBlur=0;x.fillRect(-2.4,-8,1.3,1.3);x.fillRect(1.1,-8,1.3,1.3);x.restore()}
function end(){if(done)return;done=true;I.classList.add('out');document.body.style.overflow='';setTimeout(()=>I.remove(),1600)}
$('#skip').onclick=end;setTimeout(end,7000);
(function f(){if(done&&!I.isConnected)return;x.clearRect(0,0,W,H);const t=performance.now()-t0;
if(!done&&B.length<N&&Math.random()<(t>3000?.22:.08))B.push(mk());
B.forEach((b,i)=>{b.x+=b.v*b.d;b.y+=Math.sin(b.a)*b.amp;b.a+=.05;b.w+=b.fs;bat(b);if(b.x<-120||b.x>W+120)if(done)B.splice(i,1);else B[i]=mk()});
requestAnimationFrame(f)})()})();
route();
